import ColorMatchingAPI
import Foundation
import OpenAPIRuntime
import XCTest

/// Exercises the Swift client generated by swift-openapi-generator from the
/// vendored copy of the `color_matching` `/api/v1` OpenAPI document.
///
/// See `docs/color-matching-openapi-delta.md` for the document's provenance,
/// the operationId-derived method names asserted below, and the single
/// normalization (dropping the constraint-only `anyOf` blocks on
/// `CaptureRequest` and `PairScoreRequest`) applied when vendoring.
///
/// Every response is stubbed locally through a `ClientTransport`; no live
/// server is contacted.
final class GeneratedClientTests: XCTestCase {

    private let serverURL = URL(string: "https://color-matching.example.test")!

    // MARK: - Test-sheet manifest

    func testManifestOperationBuildsSpecRequestAndDecodesTypedManifest() async throws {
        let recorded = RequestRecorder()
        let client = makeClient(recorded) { _, _, _, _ in
            Self.jsonResponse(
                200,
                #"{"schema_version":"lps-sheet-manifest/v1","sheet_id":"sheet_1","capture_profile":{"scoring_algorithm_version":"lps-distance-v1"}}"#
            )
        }

        let output = try await client.colorMatchingWeb_TestSheetController_manifest(
            .init(path: .init(sheetID: "sheet_1"))
        )

        let request = try XCTUnwrap(recorded.requests.first)
        XCTAssertEqual(request.method, .get)
        XCTAssertEqual(request.path, "/api/v1/test_sheets/sheet_1/manifest")
        XCTAssertEqual(request.operationID, "ColorMatchingWeb.TestSheetController.manifest")
        XCTAssertNil(request.body)

        guard case .ok(let ok) = output else { return XCTFail("Expected .ok, got: \(output)") }
        guard case .json(let manifest) = ok.body else { return XCTFail("Expected JSON body, got: \(ok.body)") }
        XCTAssertEqual(manifest.sheetId, "sheet_1")
        XCTAssertEqual(try Self.encodedJSON(manifest.schemaVersion), "\"lps-sheet-manifest/v1\"")
        XCTAssertEqual(try Self.encodedJSON(manifest.captureProfile.scoringAlgorithmVersion), "\"lps-distance-v1\"")
    }

    // MARK: - Recent sheets

    func testRecentSheetsOperationDecodesNullableTitle() async throws {
        let recorded = RequestRecorder()
        let client = makeClient(recorded) { _, _, _, _ in
            Self.jsonResponse(
                200,
                #"{"sheets":[{"sheet_id":"sheet_1","manifest_url":"/api/v1/test_sheets/sheet_1/manifest","title":null},{"sheet_id":"sheet_2","manifest_url":"/api/v1/test_sheets/sheet_2/manifest","title":"July LPS comparison sheet"}]}"#
            )
        }

        let output = try await client.colorMatchingWeb_TestSheetController_recent(.init())

        let request = try XCTUnwrap(recorded.requests.first)
        XCTAssertEqual(request.method, .get)
        XCTAssertEqual(request.path, "/api/v1/test_sheets/recent")

        guard case .ok(let ok) = output else { return XCTFail("Expected .ok, got: \(output)") }
        guard case .json(let recent) = ok.body else { return XCTFail("Expected JSON body, got: \(ok.body)") }
        XCTAssertEqual(recent.sheets.map(\.sheetId), ["sheet_1", "sheet_2"])
        XCTAssertNil(recent.sheets.first?.title, "The published spec allows a null title for recent sheets")
        XCTAssertEqual(recent.sheets.last?.title, "July LPS comparison sheet")
    }

    // MARK: - Ranked results

    func testRankedResultsOperationDecodesSchemaVersionAndIgnoresUntypedFields() async throws {
        let recorded = RequestRecorder()
        let client = makeClient(recorded) { _, _, _, _ in
            Self.jsonResponse(
                200,
                #"{"schema_version":"lps-ranked-results/v1","sheet_id":"sheet_1","capture_count":3,"results":[{"rank":1,"pair_id":"pair_1"}]}"#
            )
        }

        let output = try await client.colorMatchingWeb_TestSheetController_rankedResults(
            .init(path: .init(sheetID: "sheet_1"))
        )

        let request = try XCTUnwrap(recorded.requests.first)
        XCTAssertEqual(request.method, .get)
        XCTAssertEqual(request.path, "/api/v1/test_sheets/sheet_1/ranked_results")

        guard case .ok(let ok) = output else { return XCTFail("Expected .ok, got: \(output)") }
        guard case .json(let ranked) = ok.body else { return XCTFail("Expected JSON body, got: \(ok.body)") }
        XCTAssertEqual(ranked.sheetId, "sheet_1")
        XCTAssertEqual(try Self.encodedJSON(ranked.schemaVersion), "\"lps-ranked-results/v1\"")
    }

    // MARK: - Capture session creation

    func testCreateCaptureSendsMetadataAndQualityAndDecodesCaptureID() async throws {
        let recorded = RequestRecorder()
        let client = makeClient(recorded) { _, _, _, _ in
            Self.jsonResponse(201, #"{"capture_id":"cap_1"}"#)
        }

        let metadata = Components.Schemas.CaptureMetadata(
            deviceModel: "iPhone 15",
            lens: "built_in_wide_angle",
            imageWidth: 4032,
            imageHeight: 3024,
            appVersion: "0.1.0",
            timestamp: Date(timeIntervalSince1970: 0)
        )
        let requestBody = Components.Schemas.CaptureRequest(
            metadata: metadata,
            quality: .init(detectedMarkerCount: 4, blurScore: 0.75, rejections: [])
        )

        let output = try await client.colorMatchingWeb_CaptureController_create(
            .init(path: .init(sheetID: "sheet_1"), body: .json(requestBody))
        )

        let request = try XCTUnwrap(recorded.requests.first)
        XCTAssertEqual(request.method, .post)
        XCTAssertEqual(request.path, "/api/v1/test_sheets/sheet_1/captures")
        XCTAssertEqual(request.operationID, "ColorMatchingWeb.CaptureController.create")

        let bodyJSON = try XCTUnwrap(request.bodyJSON)
        let metadataJSON = try XCTUnwrap(bodyJSON["metadata"] as? [String: Any])
        XCTAssertEqual(metadataJSON["device_model"] as? String, "iPhone 15")
        XCTAssertEqual(metadataJSON["lens"] as? String, "built_in_wide_angle")
        XCTAssertEqual(metadataJSON["image_width"] as? Int, 4032)
        XCTAssertNotNil(metadataJSON["timestamp"] as? String)
        let qualityJSON = try XCTUnwrap(bodyJSON["quality"] as? [String: Any])
        XCTAssertEqual(qualityJSON["detected_marker_count"] as? Int, 4)
        XCTAssertEqual(qualityJSON["rejections"] as? [String], [])

        guard case .created(let created) = output else { return XCTFail("Expected .created, got: \(output)") }
        guard case .json(let payload) = created.body else { return XCTFail("Expected JSON body") }
        XCTAssertEqual(payload.captureId, "cap_1")
    }

    // MARK: - Measurement upload

    func testUploadMeasurementsEncodesSpecTypedFieldsAndDecodesCounts() async throws {
        let recorded = RequestRecorder()
        let client = makeClient(recorded) { _, _, _, _ in
            Self.jsonResponse(200, #"{"capture_id":"7","measurement_count":1,"pair_score_count":0}"#)
        }

        let rgb = Components.Schemas.RgbPayload(value2: .init(r: 0.12, g: 0.1, b: 0.02))
        let requestBody = Components.Schemas.MeasurementUploadRequest(
            measurements: [
                .init(patchId: "pair_1#first", linearRgbMedian: rgb, normalizedLinearRgbMedian: rgb)
            ]
        )

        let output = try await client.colorMatchingWeb_CaptureController_uploadMeasurements(
            .init(path: .init(captureID: "7"), body: .json(requestBody))
        )

        let request = try XCTUnwrap(recorded.requests.first)
        XCTAssertEqual(request.method, .post)
        XCTAssertEqual(request.path, "/api/v1/captures/7/measurements")

        let bodyJSON = try XCTUnwrap(request.bodyJSON)
        let measurements = try XCTUnwrap(bodyJSON["measurements"] as? [[String: Any]])
        let measurement = try XCTUnwrap(measurements.first)
        // The published spec types exactly these three keys per measurement.
        // Robustness stats are not typed in the spec — a documented gap.
        XCTAssertEqual(measurement["patch_id"] as? String, "pair_1#first")
        XCTAssertEqual(measurement["linear_rgb_median"] as? [String: Double], ["r": 0.12, "g": 0.1, "b": 0.02])
        XCTAssertEqual(
            measurement["normalized_linear_rgb_median"] as? [String: Double],
            ["r": 0.12, "g": 0.1, "b": 0.02]
        )

        guard case .ok(let ok) = output else { return XCTFail("Expected .ok, got: \(output)") }
        guard case .json(let summary) = ok.body else { return XCTFail("Expected JSON body") }
        XCTAssertEqual(summary.captureId, "7")
        XCTAssertEqual(summary.measurementCount, 1)
        XCTAssertEqual(summary.pairScoreCount, 0)
    }

    // MARK: - Judgment upload

    func testUploadJudgmentsEncodesWirePayloadAndDecodesCount() async throws {
        let recorded = RequestRecorder()
        let client = makeClient(recorded) { _, _, _, _ in
            Self.jsonResponse(200, #"{"capture_id":"7","judgment_count":1}"#)
        }

        let requestBody = Components.Schemas.JudgmentUploadRequest(
            judgments: [.init(pairId: "pair_1", judgment: "near_match")]
        )

        let output = try await client.colorMatchingWeb_CaptureController_uploadJudgments(
            .init(path: .init(captureID: "7"), body: .json(requestBody))
        )

        let request = try XCTUnwrap(recorded.requests.first)
        XCTAssertEqual(request.method, .post)
        XCTAssertEqual(request.path, "/api/v1/captures/7/judgments")

        let bodyJSON = try XCTUnwrap(request.bodyJSON)
        let judgments = try XCTUnwrap(bodyJSON["judgments"] as? [[String: Any]])
        XCTAssertEqual(judgments.first?["pair_id"] as? String, "pair_1")
        XCTAssertEqual(judgments.first?["judgment"] as? String, "near_match")

        guard case .ok(let ok) = output else { return XCTFail("Expected .ok, got: \(output)") }
        guard case .json(let summary) = ok.body else { return XCTFail("Expected JSON body") }
        XCTAssertEqual(summary.captureId, "7")
        XCTAssertEqual(summary.judgmentCount, 1)
    }

    // MARK: - Error responses stay typed

    func testUnauthorizedResponseDecodesAsUnauthorizedOutputCase() async throws {
        let client = makeClient(RequestRecorder()) { _, _, _, _ in
            Self.jsonResponse(401, #"{"errors":{"detail":"Unauthorized"}}"#)
        }

        let output = try await client.colorMatchingWeb_TestSheetController_recent(.init())

        guard case .unauthorized = output else { return XCTFail("Expected .unauthorized, got: \(output)") }
    }
}

// MARK: - Helpers

private extension GeneratedClientTests {

    func makeClient(
        _ recorder: RequestRecorder,
        respond: @escaping StubTransport.Responder
    ) -> Client {
        Client(
            serverURL: serverURL,
            transport: StubTransport { request, body, baseURL, operationID in
                await recorder.record(
                    method: request.method,
                    path: request.path,
                    operationID: operationID,
                    body: body
                )
                return try await respond(request, body, baseURL, operationID)
            }
        )
    }

    static func jsonResponse(_ status: Int, _ json: String) -> (HTTPResponse, HTTPBody?) {
        (
            HTTPResponse(
                status: .init(rawValue: status)!,
                headerFields: ["Content-Type": "application/json"]
            ),
            HTTPBody(Data(json.utf8))
        )
    }

    static func encodedJSON<T: Encodable>(_ value: T) throws -> String {
        String(decoding: try JSONEncoder().encode(value), as: UTF8.self)
    }
}

/// Records the requests the generated client hands to the transport.
private final class RequestRecorder: @unchecked Sendable {
    struct RecordedRequest {
        var method: HTTPRequest.Method
        var path: String
        var operationID: String
        var body: Data?
        var bodyJSON: Any? { body.map { try? JSONSerialization.jsonObject(with: $0) } ?? nil }
    }

    private let lock = NSLock()
    private(set) var requests: [RecordedRequest] = []

    func record(method: HTTPRequest.Method, path: String, operationID: String, body: HTTPBody?) async {
        let data: Data?
        if let body {
            data = try? await Data(collecting: body, upTo: 1 << 20)
        } else {
            data = nil
        }
        lock.lock()
        defer { lock.unlock() }
        requests.append(.init(method: method, path: path, operationID: operationID, body: data))
    }
}

/// A `ClientTransport` that answers from a closure instead of the network.
private struct StubTransport: ClientTransport {
    typealias Responder = (HTTPRequest, HTTPBody?, URL, String) async throws -> (HTTPResponse, HTTPBody?)

    private let respond: Responder

    init(_ respond: @escaping Responder) {
        self.respond = respond
    }

    func send(
        _ request: HTTPRequest,
        body: HTTPBody?,
        baseURL: URL,
        operationID: String
    ) async throws -> (HTTPResponse, HTTPBody?) {
        try await respond(request, body, baseURL, operationID)
    }
}
